Author: Zahra W.M', 'https://ikgoijeipxyfsbvgfibd.supabase.co/storage/v1/object/public/news-images/1773716134264-cropped-colleagues-generating-business-ideas%20(1)%20(1).jpg', 'Published', false, '2026-03-17', '2026-03-17 02:49:02.593616', '52d16937-03a6-4735-88cb-ea9f48cd0ea1'), (56, 'THR: Tradisi Tahunan yang Perlu Dikelola Secara Bijak', 'thr-tradisi-tahunan-yang-perlu-dikelola-secara-bijak', 'Legal Insight', 'Menjelang hari raya, Tunjangan Hari Raya (THR) sangat dinanti pekerja sebagai tambahan pendapatan dan penghargaan dari perusahaan. THR wajib diberikan sesuai regulasi ketenagakerjaan, dengan besaran tergantung masa kerja. Namun, masalah pembayaran sering muncul, sehingga perusahaan perlu memenuhi kewajiban ini. Pekerja juga sebaiknya mengelola THR untuk masa depan.', 'Menjelang perayaan hari raya keagamaan di Indonesia, Tunjangan Hari Raya atau THR menjadi salah satu hal yang paling ditunggu oleh para pekerja. Bagi banyak karyawan, THR bukan hanya tambahan pendapatan, tetapi juga bentuk penghargaan dari perusahaan atas kontribusi dan kinerja yang telah diberikan selama bekerja. Dana ini biasanya dimanfaatkan untuk berbagai kebutuhan menjelang hari raya, seperti persiapan keluarga, biaya perjalanan mudik, hingga berbagi dengan kerabat.

Di Indonesia, pemberian THR bukan sekadar kebiasaan, melainkan kewajiban yang telah diatur dalam regulasi ketenagakerjaan. Perusahaan diwajibkan memberikan THR kepada pekerja yang telah bekerja minimal satu bulan secara terus-menerus. Besaran THR umumnya setara dengan satu kali gaji bagi karyawan yang memiliki masa kerja satu tahun atau lebih, sedangkan bagi yang masa kerjanya kurang dari satu tahun akan dihitung secara proporsional. Aturan ini bertujuan untuk melindungi hak pekerja sekaligus menciptakan hubungan kerja yang lebih adil antara perusahaan dan karyawan.

Meski demikian, permasalahan terkait pembayaran THR masih sering terjadi di berbagai tempat kerja. Tidak jarang ditemukan kasus keterlambatan pembayaran atau bahkan perusahaan yang tidak memenuhi kewajiban tersebut. Situasi seperti ini tentu dapat menimbulkan ketidakpastian bagi para pekerja, terlebih menjelang hari raya ketika kebutuhan finansial biasanya meningkat. Karena itu, penting bagi perusahaan untuk memahami kewajiban hukumnya serta merencanakan kondisi keuangan dengan baik agar pembayaran THR dapat dilakukan tepat waktu.

Di sisi lain, pekerja juga perlu mengelola THR secara lebih bijak. Selain digunakan untuk kebutuhan hari raya, sebagian dana tersebut sebaiknya dialokasikan untuk tabungan, investasi, atau kebutuhan masa depan lainnya. Dengan pengelolaan yang tepat, THR tidak hanya memberikan manfaat sesaat, tetapi juga dapat membantu meningkatkan stabilitas keuangan dalam jangka panjang.

Dalam praktik dunia usaha, kepatuhan terhadap aturan ketenagakerjaan, termasuk kewajiban pembayaran THR, merupakan bagian penting dari tata kelola perusahaan yang baik. Dengan memahami aspek hukum yang mengatur hubungan kerja, perusahaan dapat meminimalkan potensi konflik atau sengketa dengan karyawan.

Apabila perusahaan membutuhkan pendampingan terkait aspek hukum ketenagakerjaan, seperti penyusunan kontrak kerja, kebijakan internal, maupun kepatuhan terhadap regulasi yang berlaku, MAS Lawfirm siap membantu memberikan solusi hukum yang profesional dan terpercaya.', 'https://ikgoijeipxyfsbvgfibd.supabase.co/storage/v1/object/public/news-images/1773840870096-Ilustrasi%20THR.jpeg', 'Published', false, '2026-03-17', '2026-03-17 03:34:52.791086', '4b2681d8-d113-455b-aaf8-41b5502658f0'), (57, 'Penguatan Regulasi Zakat dan Implikasinya dalam Hukum Indonesia', 'penguatan-regulasi-zakat-dan-implikasinya-dalam-hukum-indonesia', 'Legal Insight', 'Zakat adalah kewajiban ibadah dan aspek hukum yang berkembang di Indonesia. Pengelolaan zakat harus dilakukan oleh lembaga resmi untuk transparansi. Masih ada isu hukum, seperti lembaga tidak berizin. Penguatan regulasi dan pengawasan penting untuk meningkatkan akuntabilitas zakat. ', 'Zakat tidak hanya menjadi kewajiban ibadah, tetapi juga memiliki aspek hukum yang terus berkembang di Indonesia. Melalui Undang-Undang Nomor 23 Tahun 2011, negara menegaskan bahwa pengelolaan zakat harus dilakukan oleh lembaga resmi seperti BAZNAS dan LAZ agar lebih tertib, transparan, dan tepat sasaran.

Dalam praktiknya, ada beberapa isu hukum yang masih muncul, seperti keberadaan lembaga zakat yang belum berizin, lemahnya pengawasan, serta potensi tumpang tindih kewenangan. Selain itu, perkembangan teknologi juga mendorong munculnya layanan zakat digital yang perlu diimbangi dengan kepastian hukum, terutama terkait keamanan data dan transaksi.

Ke depan, penguatan regulasi dan pengawasan menjadi penting agar pengelolaan zakat semakin akuntabel dan mampu memberikan manfaat maksimal bagi masyarakat.

Apabila Anda memerlukan informasi atau konsultasi terkait berbagai persoalan hukum, M.A.S Law Firm siap memberikan layanan konsultasi dan pendampingan hukum secara profesional. Didukung oleh pengacara terbaik Indonesia, **Adv. Muhamad Amar, S.H., S.M., M.M., CTT** dan **Adv. A.K.H. Hasibuan, S.H., S.Si., M.Si., CPM, CHT, M.A.S** Law Firm berkomitmen memberikan solusi hukum yang tepat dan berlandaskan kepastian hukum. Informasi lebih lanjut dapat diakses melalui Instagram [@m.a.s.lawfirm](https://www.instagram.com/m.a.s.lawfirm?utm_source=ig_web_button_share_sheet&igsh=ZDNlZDc0MzIxNw==), [lynk. id MAS Law Firm](https://lynk.id/maslawfirm), atau klik nomor WhatsApp di pojok kanan.

Author: Elok✍️', 'https://ikgoijeipxyfsbvgfibd.supabase.co/storage/v1/object/public/news-images/1773727160338-69530.png', 'Published', false, '2026-03-17', '2026-03-17 05:19:48.383101', 'af05b4a6-74d1-4452-9a62-58d101bd9f80'), (58, 'Bukan Sekadar Gelar: Mengapa Penguasaan Hard Skill di Luar Kampus Semakin Krusial', 'bukan-sekadar-gelar-mengapa-penguasaan-hard-skill-di-luar-kampus-semakin-krusial', 'General Insight', 'Di tengah persaingan kerja yang ketat, gelar akademis tidak lagi menjadi faktor utama untuk sukses. Perusahaan lebih menghargai keterampilan nyata. Hard skill, yang sering diperoleh di luar pendidikan formal, penting untuk memenuhi kebutuhan spesifik industri dan meningkatkan daya saing. Kombinasi gelar dan keterampilan praktis menciptakan individu yang kompeten.', 'Di tengah persaingan kerja yang semakin ketat, memiliki gelar akademis tak lagi menjadi satu-satunya faktor penentu dalam mencapai sukses karir. Kini, banyak perusahaan yang lebih fokus pada keterampilan nyata yang dapat langsung diterapkan di tempat kerja. Ini menjadi alasan mengapa kemampuan dalam hard skill di luar pendidikan formal sangat penting.

**Realita Dunia Kerja Saat Ini**

Inovasi teknologi dan tuntutan industri yang terus berubah memaksa individu untuk selalu mengembangkan diri. Para lulusan universitas memang dilengkapi dengan teori dan dasar ilmiah, tetapi lingkungan kerja menuntut lebih dari itu, yaitu keterampilan praktis, kemampuan beradaptasi dengan cepat, serta pemecahan masalah yang efektif.

Sebagai ilustrasi, seorang lulusan hukum tidak hanya diwajibkan untuk memahami teori undang-undang, tetapi juga harus:
- Menyusun dokumen hukum dengan baik
- Menganalisis kasus secara mendalam
- Membangun komunikasi yang baik dengan klien
- Mengetahui praktik hukum yang berlaku di lapangan

Semua kemampuan tersebut adalah hard skill yang sering kali justru diperoleh di luar perkuliahan.

**Mengapa Hard Skill Eksternal Itu Penting?**

Ada beberapa alasan mendasar mengapa hard skill yang didapat dari luar kampus sangat esensial:

**1. Kebutuhan Spesifik dari Industri**
Perusahaan menginginkan calon karyawan yang langsung dapat berkontribusi, bukan sekadar yang bersedia belajar. Mereka mencari individu yang sudah memiliki keterampilan teknis yang relevan.

**2. Meningkatkan Daya Saing**
Dengan banyaknya lulusan baru setiap tahunnya, hanya memiliki gelar tidak cukup untuk menonjol. Hard skill menjadi faktor penting yang membedakan seseorang dari kandidat lainnya.

**3. Penyesuaian dengan Perubahan**
Dunia kerja mengalami perubahan yang konstan. Individu yang terbiasa belajar di luar perguruan tinggi cenderung lebih mudah beradaptasi dan cepat menyesuaikan diri dengan perkembangan terbaru.

**4. Membuka Lebih Banyak Peluang**
Keterampilan tambahan seperti pembuatan dokumen hukum, negosiasi, pemasaran digital, dan analisis bisnis dapat membuka lebih banyak kemungkinan karir.

Penutup
Gelar adalah fondasi, tetapi *hard skill* adalah senjata utama dalam menghadapi dunia kerja. Kombinasi keduanya akan menciptakan individu yang tidak hanya kompeten secara teori, tetapi juga unggul dalam praktik.

Bagi Anda yang ingin meningkatkan kompetensi, khususnya di bidang hukum, penting untuk mendapatkan pendampingan dari pihak yang tepat. MAS Law Firm hadir sebagai mitra profesional yang tidak hanya memberikan layanan hukum, tetapi juga menjadi ruang belajar bagi pengembangan kemampuan praktis.

Didukung oleh pengacara terbaik seperti Adv. Muhammad Amar, S.H., S.M., M.M., CTT dan Adv. A.K.H. Hasibuan, S.H., S.Si., M.Si., CPM, MAS Law Firm berkomitmen memberikan solusi hukum yang profesional sekaligus berorientasi pada kualitas dan kepercayaan klien.

Karena di dunia nyata, bukan hanya apa yang Anda ketahui yang penting—tetapi apa yang bisa Anda lakukan.', 'https://ikgoijeipxyfsbvgfibd.supabase.co/storage/v1/object/public/news-images/1773735343517-ChatGPT%20Image%20Mar%2017,%202026,%2003_12_10%20PM_11zon.png', 'Published', false, '2026-03-17', '2026-03-17 08:17:08.448788', '52d16937-03a6-4735-88cb-ea9f48cd0ea1'), (59, ' Momentum Ekonomi Pasca Lebaran 2026: Peluang Baru bagi UMKM di Tengah Mobilitas Masyarakat', 'momentum-ekonomi-pasca-lebaran-2026-peluang-baru-bagi-umkm-di-tengah-mobilitas-masyarakat', 'General Insight', 'Setelah Idul Fitri, aktivitas masyarakat tetap tinggi dengan arus balik dan belanja, memberikan peluang bagi UMKM. Permintaan beralih ke produk praktis dan terjangkau. Sektor kuliner, kebutuhan rumah tangga, bisnis online, dan produk beridentitas kuat memiliki potensi. UMKM perlu menjaga kualitas, komunikasi, dan aspek hukum.', 'Setelah perayaan Idul Fitri, aktivitas masyarakat di berbagai daerah masih menunjukkan dinamika yang cukup tinggi. Arus balik, kunjungan keluarga, hingga aktivitas belanja setelah Lebaran menjadi bagian dari pergerakan ekonomi yang terus berlangsung di masyarakat. Kondisi ini secara tidak langsung membuka peluang baru bagi pelaku Usaha Mikro, Kecil, dan Menengah (UMKM) untuk tetap menjaga pertumbuhan usaha mereka setelah momentum Ramadan berakhir.

Selama bulan Ramadan dan menjelang Lebaran, sektor kuliner, fesyen, dan kebutuhan rumah tangga biasanya mengalami peningkatan permintaan yang cukup signifikan. Namun, tidak sedikit pelaku usaha yang mengalami penurunan penjualan setelah periode tersebut selesai. Oleh karena itu, penting bagi UMKM untuk memanfaatkan momentum pasca Lebaran sebagai peluang untuk memperluas pasar dan mempertahankan minat konsumen.

**Perubahan Pola Konsumsi Setelah Lebaran**

Setelah Lebaran, pola konsumsi masyarakat umumnya mulai bergeser. Jika sebelumnya masyarakat fokus pada kebutuhan Ramadan dan Hari Raya, maka setelahnya konsumen cenderung mencari produk dengan nilai praktis, harga yang lebih terjangkau, serta produk yang memiliki manfaat jangka panjang.

Perubahan ini menjadi peluang bagi pelaku UMKM untuk melakukan penyesuaian strategi usaha, baik dari sisi produk, promosi, maupun pendekatan kepada konsumen.

**Peluang Usaha yang Muncul Setelah Lebaran**

Beberapa sektor usaha yang masih memiliki potensi berkembang setelah Lebaran antara lain:


1. Kuliner dan oleh-oleh daerah
Banyak masyarakat yang kembali dari kampung halaman membawa oleh-oleh atau mencari makanan khas tertentu yang sempat populer saat Ramadan.

2. Produk kebutuhan rumah tangga
Setelah periode Lebaran, masyarakat biasanya mulai kembali fokus pada kebutuhan sehari-hari.

3. Bisnis online dan promosi digital
UMKM yang aktif memanfaatkan media sosial dan platform digital cenderung lebih mudah mempertahankan pelanggan setelah momen Lebaran.

4. Produk dengan identitas brand yang kuat
Usaha yang sudah mulai membangun nama dan identitas produk biasanya lebih mudah diingat oleh konsumen.

**Strategi UMKM Agar Tetap Bertahan Setelah Lebaran**

Agar usaha tetap berkembang setelah Lebaran, pelaku UMKM dapat mempertimbangkan beberapa strategi berikut:



- Menjaga kualitas produk dan pelayanan kepada pelanggan
- Memanfaatkan media sosial untuk menjaga komunikasi dengan konsumen
- Mengembangkan variasi produk baru setelah Ramadan
- Membangun identitas usaha yang lebih profesional


Langkah-langkah tersebut dapat membantu pelaku usaha menjaga stabilitas bisnis sekaligus membuka peluang pasar yang lebih luas.

**Pentingnya Aspek Legal dalam Mengembangkan Usaha**

Seiring berkembangnya usaha, pelaku UMKM juga perlu memperhatikan aspek hukum yang berkaitan dengan kegiatan bisnis, seperti perlindungan usaha, identitas merek, serta pengelolaan usaha yang sesuai dengan ketentuan yang berlaku.

Melalui penyediaan informasi dan edukasi hukum kepada masyarakat, M.A.S Law Firm berkomitmen membantu pelaku usaha memahami aspek hukum dalam menjalankan bisnis secara lebih aman dan berkelanjutan. Didukung oleh pengacara terbaik seperti **Adv. Muhammad Amar, S.H., S.M., M.M., CTT** dan **Adv. A.K.H. Hasibuan, S.H., S.Si., M.Si., CPM**, MAS Law Firm berkomitmen memberikan solusi hukum yang profesional sekaligus berorientasi pada kualitas dan kepercayaan klien. Informasi lebih lanjut mengenai layanan konsultasi dan pendampingan hukum dapat diakses melalui Instagram [@m.a.s.lawfirm](https://www.instagram.com/m.a.s.lawfirm?igsh=bXZnemVyYmNkb3Rp), atau [lynk.idmaslawfirm](https://lynk.id/maslawfirm).

Author : Tri Utami ', 'https://ikgoijeipxyfsbvgfibd.supabase.co/storage/v1/object/public/news-images/1774408908392-83611.png', 'Published', false, '2026-03-25', '2026-03-25 03:14:40.682262', '52d16937-03a6-4735-88cb-ea9f48cd0ea1'), (60, 'Kembali Produktif Setelah Libur Lebaran: Tips Memulai Kerja dengan Lebih Fokus', 'kembali-produktif-setelah-libur-lebaran-tips-memulai-kerja-dengan-lebih-fokus', 'General Insight', 'Libur panjang Eid al-Fitr memang ditunggu banyak orang karena waktu bersama keluarga dan suasana santai. Namun, kembali bekerja setelah liburan bisa sulit. Beberapa tips untuk membantu kembali produktif termasuk memulai dari tugas kecil, menyusun ulang prioritas, tidak memaksakan diri, dan membangun kembali rutinitas kerja.', 'Libur panjang **Eid al-Fitr** atau Lebaran memang selalu dinanti. Waktu bersama keluarga, suasana santai, hingga perjalanan mudik sering membuat kita benar-benar *“lepas”* dari rutinitas kerja.

Namun setelah liburan usai, kembali ke ritme kerja bukan hal yang mudah. Rasa malas, sulit fokus, atau bahkan kehilangan semangat sering kali muncul di hari-hari pertama kembali bekerja. Hal ini wajar, karena tubuh dan pikiran masih beradaptasi dari suasana santai ke rutinitas yang lebih terstruktur.

Agar transisi ini terasa lebih ringan, berikut beberapa tips yang bisa membantu kamu kembali produktif setelah libur Lebaran.


**1. Mulai dari Hal Kecil**

Tidak perlu langsung memaksakan diri untuk menyelesaikan semua pekerjaan sekaligus. Mulailah dari tugas-tugas yang ringan terlebih dahulu sebagai **“pemanasan”**. Langkah kecil seperti merapikan *to-do list*, atau menyelesaikan pekerjaan sederhana bisa membantu mengembalikan fokus secara perlahan. Dari sini, kamu akan lebih siap untuk mengerjakan tugas yang lebih besar.


**2. Susun Ulang Prioritas**

Setelah libur panjang, biasanya pekerjaan akan menumpuk. Agar tidak merasa kewalahan, penting untuk menyusun kembali prioritas. Pilih pekerjaan yang paling penting atau mendesak untuk diselesaikan lebih dulu. Dengan membuat urutan yang jelas, kamu **bisa bekerja lebih terarah tanpa merasa terbebani oleh banyaknya tugas.**


**3. Jangan Terlalu Keras pada Diri Sendiri**

Wajar jika di hari pertama kerja kamu belum bisa langsung produktif seperti biasanya. Memberi waktu untuk **beradaptasi adalah hal yang penting.** Alih-alih memaksakan diri, cobalah untuk bekerja secara bertahap. Dengan ritme yang lebih realistis, produktivitas justru akan kembali dengan lebih stabil.


**4. Bangun Kembali Rutinitas**

Salah satu **kunci untuk kembali produktif** adalah membangun kembali kebiasaan kerja yang sempat terhenti. Mulai dari bangun lebih pagi, mengatur waktu kerja, hingga menjaga pola aktivitas harian. Rutinitas yang konsisten akan membantu tubuh dan pikiran menyesuaikan diri lebih cepat, sehingga kamu bisa kembali fokus dalam menjalani pekerjaan.


**Penutup**

Kembali bekerja setelah libur Eid al-Fitr memang membutuhkan proses, jadi tidak perlu terburu-buru, yang terpenting adalah mulai secara perlahan dan menjaga konsistensi agar ritme kerja bisa kembali dengan lebih fokus dan produktif.

Di tengah aktivitas yang kembali berjalan, tidak ada salahnya juga untuk lebih memperhatikan kebutuhan hukum dalam pekerjaan atau bisnis Anda. Jika Anda memiliki pertanyaan atau sedang menghadapi permasalahan hukum, berkonsultasi dengan profesional hukum dapat menjadi langkah awal yang tepat untuk mendapatkan solusi yang sesuai.

Butuh konsultasi hukum? **M.A.S Law Firm** siap membantu Anda memahami situasi hukum yang dihadapi dan memberikan pendampingan yang tepat sesuai kebutuhan Anda. Didukung oleh pengacara terbaik Indonesia, **Adv. Muhamad Amar, S.H., S.M., M.M., CTT dan Adv. A.K.H. Hasibuan, S.H., S.Si., M.Si., CPM, CHT.,** yang berkomitmen memberikan pemahaman hukum yang bermanfaat serta menyediakan layanan konsultasi dan pendampingan hukum bagi pelaku usaha maupun masyarakat yang membutuhkan kepastian hukum.

