**Author: Dyan Halimah** ✍️', 'https://ikgoijeipxyfsbvgfibd.supabase.co/storage/v1/object/public/news-images/1775583742132-9f4c2428-7622-40df-9444-1c4a8bef1f96.jpeg', 'Published', false, '2026-04-07', '2026-04-07 04:56:03.893702', '52d16937-03a6-4735-88cb-ea9f48cd0ea1'), (97, 'Transformasi Dunia Kerja oleh Artificial Intelligence: Tantangan Hukum dan Perlindungan Tenaga Kerja di Era Digital', 'transformasi-dunia-kerja-oleh-artificial-intelligence-tantangan-hukum-dan-perlindungan-tenaga-kerja-di-era-digital', 'General Insight', 'Perkembangan AI meningkatkan efisiensi dan produktivitas, tetapi juga menyebabkan disrupsi tenaga kerja. Indonesia belum memiliki regulasi khusus untuk AI, dan isu hukum utama meliputi perlindungan data dan tanggung jawab. Regulasi khusus diperlukan untuk menjaga keadilan dan perlindungan hak pekerja.', 'Perkembangan teknologi ***Artificial Intelligence* (AI)** telah membawa perubahan fundamental dalam struktur dunia kerja modern. Otomatisasi berbasis AI kini digunakan dalam berbagai sektor mulai dari industri manufaktur, keuangan, hingga layanan profesional yang berdampak langsung terhadap efisiensi operasional sekaligus menggeser peran tenaga kerja manusia.

Namun di balik manfaat tersebut, muncul pertanyaan krusial: **apakah hukum di Indonesia telah siap mengatur implikasi AI terhadap tenaga kerja dan perlindungan hak pekerja?**

---

## **I. Dampak Artificial Intelligence terhadap Dunia Kerja**

Penggunaan AI memberikan dua sisi yang tidak terpisahkan:

### 1. **Efisiensi dan Produktivitas**

AI mampu:

* Mengotomatisasi pekerjaan rutin
* Mempercepat pengambilan keputusan berbasis data
* Mengurangi biaya operasional perusahaan

Teknologi ini memungkinkan organisasi untuk bekerja lebih cepat dan akurat dalam skala besar.

### 2. **Disrupsi Tenaga Kerja**

Di sisi lain:

* Pekerjaan administratif dan repetitif berpotensi tergantikan
* Terjadi perubahan struktur pekerjaan *(job shifting)*
* Muncul profesi baru berbasis teknologi

Fenomena ini menimbulkan **risiko ketenagakerjaan**, termasuk potensi pemutusan hubungan kerja (PHK) akibat otomatisasi.

---

## **II. Kerangka Regulasi di Indonesia Terkait AI dan Dunia Kerja**

Saat ini, Indonesia **belum memiliki undang-undang khusus tentang AI**, namun pengaturannya tersebar dalam beberapa regulasi yang relevan.

---

### **1. Undang-Undang Nomor 27 Tahun 2022 tentang Perlindungan Data Pribadi (UU PDP)**

UU PDP menjadi fondasi utama dalam penggunaan AI, karena:

* AI bekerja dengan mengolah data dalam jumlah besar
* Termasuk data pribadi dan data sensitif

UU ini mewajibkan:

* Persetujuan pemilik data
* Pengolahan data secara sah dan transparan
* Perlindungan terhadap kebocoran data

Pelanggaran terhadap UU PDP dapat dikenakan sanksi administratif hingga denda signifikan terhadap pelaku usaha.

➡ Dalam konteks dunia kerja:
Perusahaan yang menggunakan AI untuk rekrutmen, monitoring karyawan, atau analisis performa wajib mematuhi prinsip perlindungan data pribadi.

---

### **2. Undang-Undang Informasi dan Transaksi Elektronik (UU ITE)**

UU ITE mengatur:

* Sistem elektronik
* Aktivitas digital
* Tanggung jawab penyelenggara sistem

Dalam konteks AI:

* AI dianggap sebagai bagian dari sistem elektronik
* Pelaku usaha tetap bertanggung jawab atas output AI

Selain itu, penggunaan AI juga harus memperhatikan ketertiban umum dan tidak boleh melanggar hukum yang berlaku.

---

### **3. Undang-Undang Nomor 13 Tahun 2003 tentang Ketenagakerjaan**

Meskipun tidak secara spesifik mengatur AI, UU ini tetap relevan karena:

* Mengatur hubungan kerja
* Hak dan kewajiban pekerja
* Ketentuan PHK

➡ Dalam konteks AI:

* Perusahaan tetap wajib memenuhi hak pekerja
* PHK akibat otomatisasi harus mengikuti prosedur hukum
* Tidak boleh terjadi diskriminasi berbasis teknologi

---

### **4. Surat Edaran Menkominfo Nomor 9 Tahun 2023 tentang Etika Kecerdasan Artifisial**

Regulasi ini memberikan pedoman etika AI, antara lain:

* Transparansi
* Akuntabilitas
* Inklusivitas
* Keamanan data

Walaupun tidak mengikat secara hukum, pedoman ini menjadi dasar penting dalam tata kelola AI di Indonesia. 

---

### **5. Kebijakan Strategis: AI Nasional**

Indonesia juga memiliki:

* Strategi Nasional AI 2020–2045
* Rencana regulasi berbasis risiko

Namun hingga saat ini, regulasi AI masih dalam tahap pengembangan menuju sistem yang lebih komprehensif. 

---

## **III. Isu Hukum Utama dalam Penggunaan AI di Dunia Kerja**

### **1. Perlindungan Data dan Privasi**

AI membutuhkan data dalam jumlah besar → berpotensi melanggar privasi jika tidak dikontrol.

➡ Risiko:

* Penyalahgunaan data karyawan
* Pelanggaran hak privasi

---

### **2. Tanggung Jawab Hukum (Liability)**

Jika AI melakukan kesalahan:

* Siapa yang bertanggung jawab?

  * Perusahaan?
  * *Developer* AI?
  * Operator?

Saat ini, hukum Indonesia masih menempatkan tanggung jawab pada **pengguna atau penyelenggara sistem**.

---

### **3. Diskriminasi Algoritmik**

AI dalam rekrutmen dapat:

* Menghasilkan bias
* Mendiskriminasi kandidat tertentu

➡ Ini berpotensi melanggar prinsip keadilan dalam hukum ketenagakerjaan.

---

### **4. PHK dan Transformasi Tenaga Kerja**

Penggunaan AI dapat menyebabkan:

* Pengurangan tenaga kerja
* Perubahan struktur organisasi

Namun:

* Hak pekerja tetap harus dilindungi
* PHK harus sesuai prosedur hukum

---

## **IV. Tantangan Regulasi di Indonesia**

Beberapa tantangan utama:

### ⚠️ 1. Belum ada UU khusus AI

➡ Menyebabkan **ketidakpastian hukum** ([Universitas Pancasila Journal][4])

### ⚠️ 2. Regulasi masih sektoral

➡ Terpisah antara UU PDP, UU ITE, dan ketenagakerjaan

### ⚠️ 3. Perkembangan teknologi lebih cepat dari hukum

➡ Regulasi sering tertinggal dari praktik di lapangan

---

## **V. Analisis dan Rekomendasi Hukum**

Untuk menjawab tantangan tersebut, diperlukan:

### ✔ 1. Pembentukan Regulasi Khusus AI

* Mengatur tanggung jawab hukum
* Menetapkan standar keamanan dan etika

### ✔ 2. Integrasi dengan Hukum Ketenagakerjaan

* Perlindungan pekerja terdampak otomatisasi
* Program *reskilling* dan *upskilling*

### ✔ 3. Penguatan Pengawasan Data

* Implementasi ketat UU PDP
* Audit penggunaan AI di perusahaan

---

## **VI. Kesimpulan**

Artificial Intelligence merupakan teknologi yang tidak dapat dihindari dalam transformasi dunia kerja. Namun, implementasinya harus diimbangi dengan kerangka hukum yang memadai.

Di Indonesia:

* **UU PDP, UU ITE, dan UU Ketenagakerjaan** menjadi dasar hukum sementara
* Namun belum cukup untuk mengakomodasi kompleksitas AI

Oleh karena itu, diperlukan pendekatan hukum yang:

* Adaptif
* Komprehensif
* Berorientasi pada perlindungan tenaga kerja

Sehingga AI tidak hanya menjadi alat efisiensi, tetapi juga tetap selaras dengan prinsip keadilan dan perlindungan hukum.

---

Perkembangan teknologi seperti Artificial Intelligence menghadirkan tantangan hukum yang semakin kompleks bagi pelaku usaha dan tenaga kerja. Pendampingan hukum yang tepat menjadi kunci dalam memastikan kepatuhan regulasi sekaligus meminimalisir risiko hukum.

MAS Law Firm hadir untuk memberikan solusi hukum strategis dalam menghadapi dinamika era digital. Untuk mendapatkan lebih banyak informasi seputar insight sehari-hari dapat diakses melalui **Instagram [@m.a.s.lawfirm](https://www.instagram.com/m.a.s.lawfirm/)**, **[lynk.idmaslawfirm](https://lynk.id/maslawfirm)**, atau klik nomor **WhatsApp di pojok kanan bawah**.


Author: Inzaghi ✍️', 'https://ikgoijeipxyfsbvgfibd.supabase.co/storage/v1/object/public/news-images/1775546767661-Gemini_Generated_Image_x2x9xfx2x9xfx2x9%20(1).png', 'Published', false, '2026-04-07', '2026-04-07 07:26:11.215399', '52d16937-03a6-4735-88cb-ea9f48cd0ea1'), (98, 'Transformasi Layanan Legalitas Usaha: Update Pendaftaran HAKI dan Pendirian PT/CV di Indonesia ', 'transformasi-layanan-legalitas-usaha-update-pendaftaran-haki-dan-pendirian-pt-cv-di-indonesia', 'Legal Insight', 'Artikel ini membahas update prosedur pendaftaran HAKI serta pendirian PT/CV di Indonesia berdasarkan OSS RBA dan UU Cipta Kerja. Memuat tahapan, dasar hukum, serta pentingnya legalitas usaha bagi pelaku bisnis agar berjalan aman dan sesuai regulasi.', 'Pemerintah Indonesia terus memberdayakan sistem perizinan bisnis dan perlindungan hak kekayaan intelektual untuk mempermudah proses berbisnis. Dengan penerapan Undang-Undang Cipta Kerja dan peraturan turunan yang menyertainya, serta penguatan sistem digital melalui OSS (*Online Single Submission*) yang berbasis risiko (RBA) dan Direktorat Jenderal Kekayaan Intelektual (DJKI), kini proses legalitas usaha menjadi lebih terintegrasi, transparan, dan efisien.

Tulisan ini mengulas perkembangan terbaru terkait dengan prosedur pendirian PT/CV dan pendaftaran Hak Kekayaan Intelektual (HAKI) di Indonesia.

**1. Prosedur Terbaru Pendidirian PT dan CV**

**a. Implementasi OSS Berbasis Risiko (RBA)**

Melalui sistem OSS RBA, izin usaha dikategorikan menurut tingkat risiko dari kegiatan usaha, yaitu risiko rendah, menengah, dan tinggi.
Pendekatan ini menetapkan jenis izin yang harus dipenuhi oleh pelaku bisnis, mulai dari Nomor Induk Berusaha (NIB) hingga izin tambahan sesuai dengan sektor usaha.

**b. Kemudahan dalam Mendirikan PT (Termasuk PT Perorangan)**

Menurut ketentuan dalam UU Cipta Kerja:
- PT sekarang dapat didirikan oleh **satu orang** untuk kategori usaha mikro dan kecil (PT Perorangan).
- Proses pendaftaran dilakukan secara daring.
- Tidak diperlukan akta notaris dalam bentuk tradisional untuk PT Perorangan.

Sementara itu, pendirian PT biasa dan CV masih memerlukan notaris, namun proses administrasinya sudah terintegrasi secara digital dengan sistem pemerintah.

**c. Digitalisasi Pengelolaan dan Penyatuan Sistem**

Langkah-langkah seperti:
- Pendaftaran nama perusahaan
- Pembuatan dokumen resmi
- Validasi entitas hukum
- Pengeluaran NIB

Telah saling terhubung dengan cara yang teratur melalui OSS dan AHU *Online*, sehingga mempercepat proses dan mengurangi hambatan administratif.

**2. Prosedur Terbaru Pendaftaran HAKI**

Pendaftaran HAKI, khususnya merek, diatur dan dikelola oleh DJKI Kementerian Hukum dan HAM dengan sistem berbasis elektronik.

**a. Pengajuan Permohonan Secara Online**

Permohonan pendaftaran merek kini dilakukan melalui sistem *online* DJKI, yang mencakup:
- Pengisian data pemohon
- Unggah dokumen
- Pembayaran biaya resmi

**b. Tahapan Pemeriksaan Merek**

Proses pendaftaran meliputi:
- Pemeriksaan formalitas
- Pengumuman (publikasi)
- Pemeriksaan substantif

Tahapan ini bertujuan memastikan bahwa merek yang didaftarkan tidak memiliki persamaan pada pokoknya dengan merek terdaftar lainnya.

**c. Pentingnya Klasifikasi Merek**

Pemohon wajib menentukan kelas merek sesuai dengan jenis barang/jasa berdasarkan klasifikasi internasional (*Nice Classification*). Kesalahan dalam pemilihan kelas dapat berdampak pada terbatasnya perlindungan hukum.

**3. Pentingnya Legalitas dan Perlindungan HAKI bagi Pelaku Usaha**

Keberadaan legalitas usaha serta perlindungan HAKI memainkan peranan penting dalam mendukung kelangsungan kegiatan bisnis, antara lain:
- Memberikan kepastian di ranah hukum
- Meningkatkan reputasi bisnis di mata rekan dan investor
- Melindungi identitas serta kekayaan intelektual dari kemungkinan konflik
- Mendukung pengembangan usaha baik secara domestik maupun internasional

**4. Kendala dalam Pelaksanaan di Lapangan**

Walaupun sistem telah terintegrasi dan menggunakan teknologi digital, pada kenyataannya pelaku usaha masih menghadapi sejumlah tantangan, seperti:
- Minimnya pemahaman mengenai sistem OSS dan langkah hukum yang harus diambil
- Kesalahan dalam pengisian informasi atau dokumen
- Penolakan terhadap pendaftaran merek karena kesamaan dengan merek lain
- Ketidaksesuaian dalam pemilihan jenis entitas usaha

Oleh karena itu, mendapatkan bantuan hukum yang tepat dapat sangat membantu memastikan bahwa proses berlangsung sesuai dengan peraturan yang ada.

**Penutup**

Evolusi kebijakan dan digitalisasi layanan pemerintah di sektor legalitas usaha serta HAKI merupakan langkah penting dalam menciptakan lingkungan bisnis yang lebih mendukung. Namun demikian, pemahaman yang mendalam mengenai prosedur dan regulasi tetap penting bagi pelaku usaha untuk menghindari masalah hukum di masa depan.

MAS LAW FIRM hadir sebagai mitra profesional dalam membantu pendirian PT, CV, serta pendaftaran HAKI dengan cara yang tepat, efisien, dan sesuai dengan peraturan hukum yang berlaku.
Didukung oleh tim yang berpengalaman, kami bertekad memberikan layanan terbaik untuk menjamin legalitas usaha Anda.
MAS LAW FIRM Solusi Legalitas Usaha Anda bersama Pengacara Terbaik.

