Autor: Inzaghi ✍️', 'https://ikgoijeipxyfsbvgfibd.supabase.co/storage/v1/object/public/news-images/1776155625420-Judi%20Online%20(Judol).jfif', 'Published', false, '2026-04-14', '2026-04-14 08:33:52.12285', '52d16937-03a6-4735-88cb-ea9f48cd0ea1'), (112, 'Maraknya Jasa Titip (Jastip) dan Personal Shopper: Peluang Besar, Tapi Sudah Sesuai Hukum?', 'maraknya-jasa-titip-jastip-dan-personal-shopper-peluang-besar-tapi-sudah-sesuai-hukum', 'Legal Insight', 'Tren jasa titip (jastip) dan personal shopper kian populer seiring meningkatnya minat belanja produk luar. Meski terlihat sederhana, aktivitas ini memiliki aspek hukum terkait legalitas usaha, perlindungan konsumen, dan aturan impor yang perlu diperhatikan pelaku usaha.', 'Fenomena jasa titip dan *personal shopper* telah berkembang pesat dalam beberapa tahun terakhir, terutama dengan meningkatnya ketertarikan masyarakat pada produk internasional dan barang edisi terbatas. Melalui platform media sosial, banyak orang dan pemilik usaha menyediakan layanan pembelian barang mulai dari kota lain hingga luar negeri dengan metode pre-order.
Di balik kesempatan bisnis yang menjanjikan ini, ada berbagai aspek hukum yang sering kali belum sepenuhnya dipahami.

**Bisnis Jastip: Di Antara Personal dan Komersial**

Sebagian besar orang yang terlibat dalam jastip memandang aktivitas ini hanya sebagai “titip beli” antar individu saja. Namun, apabila kegiatan ini dijalankan secara konsisten dan mendatangkan profit, maka secara hukum, aktivitas tersebut sudah dapat dianggap sebagai usaha.
Ini berarti terdapat tanggung jawab yang harus diperhatikan, seperti:


- Memiliki legalitas dalam usaha.
- Mematuhi peraturan perpajakan.
- Melakukan transaksi dengan cara yang transparan.

**Risiko Sengketa dengan Konsumen**

Salah satu isu yang sering timbul dalam bisnis jastip adalah ketidakcocokan barang, keterlambatan pengiriman, hingga pembatalan sepihak. Tanpa adanya kesepakatan yang jelas, posisi pelaku usaha bisa menjadi rentan ketika terjadi keluhan atau sengketa.
Dalam hal perlindungan bagi konsumen, pelaku jastip tetap bertanggung jawab terhadap barang yang dipasarkan, meskipun hanya berfungsi sebagai perantara.

**Potensi Pelanggaran Impor dan Bea Cukai**

Dalam konteks jastip internasional, hal kepabeanan menjadi sangat krusial. Semua barang yang tiba di Indonesia harus mematuhi aturan impor, termasuk memenuhi ambang nilai dan kewajiban pajak yang berlaku.
Apabila tidak sesuai regulasi, barang tersebut bisa ditahan di kantor bea cukai atau bahkan dapat dikenakan tindakan hukuman.

**Pentingnya Sistem dan Dokumentasi**

Supaya kegiatan jastip lebih aman, para pelaku bisnis disarankan untuk:
- Menyusun ketentuan dan syarat yang jelas
- Memberikan faktur atau bukti transaksi yang sah
- Menyampaikan perkiraan waktu dan potensi risiko kepada konsumen
- Menerapkan sistem pembayaran yang transparan dan terdokumentasi

