Untuk mendapatkan lebih banyak informasi seputar insight sehari-hari dapat diakses melalui **Instagram [@m.a.s.lawfirm](https://www.instagram.com/m.a.s.lawfirm/)**, **[lynk.idmaslawfirm](https://lynk.id/maslawfirm)**, atau klik nomor **WhatsApp di pojok kanan bawah**.', 'https://ikgoijeipxyfsbvgfibd.supabase.co/storage/v1/object/public/news-images/1776908151309-WhatsApp%20Image%202026-04-21%20at%2016.46.34.jpeg', 'Published', false, '2026-04-21', '2026-04-21 09:08:28.239956', '52d16937-03a6-4735-88cb-ea9f48cd0ea1'), (123, 'Refleksi Hari Kartini 2026: Kesetaraan Gender di Dunia Kerja Masih Hadapi Tantangan', 'refleksi-hari-kartini-2026-kesetaraan-gender-di-dunia-kerja-masih-hadapi-tantangan', 'General Insight', 'Peringatan Hari Kartini pada 21 April mengingatkan usaha Raden Ajeng Kartini untuk emansipasi wanita. Meskipun ada kemajuan, kesetaraan gender masih sulit, terutama dalam pekerjaan. Upaya kolaborasi antara perusahaan, pemerintah, dan masyarakat diperlukan untuk mencapai kesetaraan.', 'Tangerang - Peringatan Hari Kartini setiap tanggal 21 April menjadi waktu yang tepat untuk merenungkan usaha Raden Ajeng Kartini dalam memajukan emansipasi wanita di Indonesia. Akan tetapi, di zaman yang serba modern ini, masalah kesetaraan gender, khususnya di sektor pekerjaan, masih menjadi isu yang belum sepenuhnya teratasi.

Menteri Pemberdayaan Perempuan dan Perlindungan Anak mengungkapkan bahwa berbagai rintangan dalam mencapai kesetaraan gender masih ada, mulai dari akses ekonomi hingga peran serta wanita dalam pembangunan.

**A. Kemajuan Kesetaraan Gender, Namun Belum Merata**

Data dari Badan Pusat Statistik (BPS) menunjukkan bahwa Indeks Ketimpangan Gender (IKG) Indonesia terus menunjukkan perbaikan dan mencapai angka sekitar 0,421 pada tahun 2024.

Angka ini menunjukkan adanya kemajuan, khususnya dalam sektor tenaga kerja. Namun, masih terdapat kesenjangan dalam berbagai bidang, termasuk:
- Partisipasi kerja perempuan yang masih di bawah laki-laki
- Akses ke posisi kepemimpinan
- Peluang ekonomi yang tidak merata

Dengan kata lain, meskipun ada kemajuan, namun belum benar-benar mencakup semua aspek.

**B. Tantangan Nyata dalam Dunia Kerja**

Di tengah perkembangan saat ini, perempuan semakin berperan aktif di berbagai bidang profesional. Namun, beberapa tantangan klasik masih tetap ada, di antaranya:
1. Kesenjangan Upah: Perempuan sering kali menerima gaji yang lebih rendah untuk pekerjaan yang sama.
2. Glass Ceiling: Banyak perempuan menghadapi hambatan tak terlihat dalam mencapai posisi tinggi.
3. Diskriminasi dan Stereotip: Masih ada anggapan bahwa perempuan memiliki batasan tertentu dalam dunia pekerjaan.
4. Beban Ganda: Perempuan sering kali harus menjalani peran ganda antara pekerjaan dan tanggung jawab rumah tangga.

Fenomena ini menunjukkan bahwa perjuangan untuk kesetaraan belum sepenuhnya tercapai, sejalan dengan semangat Kartini yang masih relevan hingga saat ini.

**C. Kartini dan Relevansinya di Era Digital**

Lebih dari seratus tahun yang lalu, Raden Ajeng Kartini berjuang untuk hak-hak perempuan dalam mendapatkan pendidikan dan kebebasan untuk berpikir.

Saat ini, semangat tersebut berkembang menjadi:
- Kesetaraan akses dalam pekerjaan
- Kesempatan karier yang adil
- Lingkungan kerja yang inklusif

Hari Kartini bukan sekadar perayaan simbolis, tetapi juga pengingat bahwa kesetaraan gender adalah suatu proses yang terus berlangsung.

**D. Peran Hukum dan Kebijakan dalam Mendorong Kesetaraan**

Secara formal, Indonesia telah memiliki landasan hukum yang mendukung kesetaraan, seperti:
- Konstitusi yang menjamin hak yang setara
- Peraturan ketenagakerjaan yang melarang adanya diskriminasi
- Kebijakan perlindungan bagi pekerja wanita

Namun, tantangan terbesar terletak pada pelaksanaannya di lapangan.

Oleh karena itu, pendekatan yang diperlukan tidak hanya:
- Penegakan hukum
- Tetapi juga edukasi dan perubahan budaya kerja

**E. Kolaborasi sebagai Kunci**

Langkah untuk mencapai kesetaraan gender memerlukan partisipasi dari berbagai pihak:
1. Perusahaan: Menciptakan tempat kerja yang inklusif dan bebas diskriminasi
2. Pemerintah: Memperkuat regulasi dan pengawasan
3. Masyarakat: Mendorong perubahan sikap terhadap peran wanita

Pendekatan kolaboratif ini dianggap sebagai strategi yang efektif untuk mempercepat pencapaian kesetaraan yang lebih berarti.

Kesetaraan gender di Indonesia memang menunjukkan perkembangan yang positif, namun tetap menghadapi berbagai tantangan baik struktural maupun sosial. Momen Hari Kartini mengingatkan kita bahwa perjuangan ini belum usai. Kesetaraan bukan hanya hak perempuan, tetapi juga merupakan bagian dari pembangunan yang adil dan berkelanjutan.

Sebagai bagian dari komunitas profesional, M.A.S Law Firm mendukung terciptanya sistem kerja yang adil, setara, dan bebas diskriminasi. Melalui pemahaman hukum yang tepat, baik bagi perusahaan maupun pekerja, diharapkan tercipta hubungan kerja yang sehat-sejalan dengan semangat Kartini di era modern.

Apabila Anda memerlukan informasi atau konsultasi terkait berbagai persoalan hukum, M.A.S Law Firm siap memberikan layanan konsultasi dan pendampingan hukum secara profesional. Didukung oleh pengacara terbaik Indonesia, **Adv. Muhamad Amar, S.H., S.M., M.M., CTT** dan **Adv. A.K.H. Hasibuan, S.H., S.Si., M.Si., CPM, CHT,** **M.A.S Law Firm** berkomitmen memberikan solusi hukum yang tepat dan berlandaskan kepastian hukum.

