**Author: [Citra M](https://www.instagram.com/citt10_/)** ✍️
', 'https://ikgoijeipxyfsbvgfibd.supabase.co/storage/v1/object/public/news-images/1778216534415-ChatGPT%20Image%208%20Mei%202026,%2012.00.03%20(1).png', 'Published', true, '2026-05-08', '2026-05-08 05:29:57.101488', '1d9a1d84-b781-49d2-bc3b-4a792a49349a'), (149, 'Pemerintah Resmi Atur Hukum Adat Lewat PP Baru, Apa Dampaknya bagi Masyarakat?', 'pemerintah-resmi-atur-hukum-adat-lewat-pp-baru-apa-dampaknya-bagi-masyarakat', 'Legal Insight', ' Pemerintah resmi mengatur penerapan hukum adat melalui aturan baru sebagai bagian dari implementasi KUHP nasional. Kebijakan ini bertujuan mengakui hukum yang hidup di masyarakat, namun tetap dibatasi agar tidak bertentangan dengan HAM dan hukum negara.', 'Pemerintah Resmi Atur Hukum Adat Lewat PP Baru, Apa Dampaknya bagi Masyarakat?

Pemerintah resmi menerbitkan aturan pelaksana mengenai hukum yang hidup dalam masyarakat atau yang lebih dikenal sebagai hukum adat. Kebijakan ini menjadi salah satu langkah penting setelah disahkannya Kitab Undang-Undang Hukum Pidana (KUHP) baru yang mulai mengakomodasi keberadaan norma dan hukum adat di Indonesia.

Kehadiran aturan ini langsung menarik perhatian publik. Di satu sisi, banyak pihak menilai kebijakan tersebut menjadi bentuk pengakuan negara terhadap nilai-nilai hukum lokal yang selama ini hidup di tengah masyarakat. Namun di sisi lain, muncul pula kekhawatiran terkait potensi multitafsir hingga penyalahgunaan dalam penerapannya.

Lalu, seperti apa sebenarnya aturan baru tersebut dan apa dampaknya bagi masyarakat?



## Hukum Adat Kini Diakui dalam Sistem Hukum Nasional

Indonesia dikenal sebagai negara dengan keberagaman budaya dan adat istiadat yang sangat luas. Di berbagai daerah, masyarakat masih menjalankan norma adat yang diwariskan turun-temurun untuk mengatur kehidupan sosial.

Melalui KUHP baru, negara mulai mengakui keberadaan “hukum yang hidup dalam masyarakat” sebagai bagian dari sistem hukum nasional. Artinya, norma adat tertentu dapat menjadi dasar penjatuhan sanksi sepanjang memenuhi syarat dan diatur secara resmi.

Untuk memperjelas penerapannya, pemerintah kemudian menerbitkan Peraturan Pemerintah (PP) sebagai aturan pelaksana agar hukum adat tidak diterapkan secara sembarangan.



## Apa Isi Pokok Aturan Baru Ini?

Aturan pelaksana tersebut pada dasarnya mengatur bagaimana hukum adat dapat diterapkan dalam sistem pidana nasional.

Pemerintah menegaskan bahwa tidak semua norma adat otomatis bisa dijadikan dasar pemidanaan. Ada sejumlah syarat yang harus dipenuhi, di antaranya:

- Hukum adat tersebut benar-benar masih hidup dan dipatuhi masyarakat
- Tidak bertentangan dengan Pancasila dan UUD 1945
- Selaras dengan prinsip hak asasi manusia
- Memiliki batasan dan mekanisme yang jelas

Dengan adanya aturan ini, negara ingin memastikan bahwa pengakuan terhadap hukum adat tetap berada dalam koridor hukum nasional dan tidak melanggar hak warga negara.



## Negara Tegaskan Ada Batas Pemidanaan

Salah satu poin penting dalam aturan ini adalah penegasan bahwa hukum adat tidak boleh digunakan secara berlebihan atau sewenang-wenang.

Pemerintah menekankan bahwa pemidanaan berbasis hukum adat tetap memiliki batas yang jelas. Artinya, sanksi yang diberikan harus proporsional dan tidak boleh bertentangan dengan prinsip keadilan modern.

Negara juga menegaskan bahwa penerapan hukum adat tidak dapat menggantikan seluruh sistem hukum nasional. Hukum adat hanya diakui dalam konteks tertentu yang benar-benar hidup dan diakui masyarakat setempat.

Langkah ini dilakukan untuk mencegah munculnya praktik diskriminatif atau penghukuman yang melanggar hak asasi manusia.



## Satpol PP Berpotensi Jadi Penyidik Pelanggaran Norma Lokal

Salah satu hal yang cukup menarik perhatian publik adalah kemungkinan keterlibatan Satpol PP dalam penegakan pelanggaran norma lokal atau hukum adat tertentu.

Dalam implementasinya nanti, aparat daerah dapat memiliki peran dalam menindak pelanggaran yang berkaitan dengan aturan lokal yang telah diakui pemerintah daerah.

Namun, kewenangan tersebut tetap harus mengikuti prosedur hukum yang berlaku dan tidak dapat dilakukan secara sepihak tanpa dasar aturan yang jelas.

Hal ini memunculkan perdebatan di masyarakat. Sebagian menilai langkah tersebut dapat membantu menjaga ketertiban sosial dan budaya lokal. Namun ada juga yang khawatir aturan ini bisa menimbulkan penyalahgunaan kewenangan jika tidak diawasi secara ketat.



## Kenapa Pemerintah Mengatur Hukum Adat Sekarang?

Pemerintah menilai keberadaan hukum adat sebenarnya sudah lama hidup di masyarakat Indonesia, tetapi belum memiliki kepastian dalam sistem hukum nasional.

Dengan adanya aturan resmi, pemerintah ingin:

1. memberikan kepastian hukum
2. menjaga keberagaman budaya lokal
3. menghindari konflik antara hukum adat dan hukum nasional
4. memperjelas batas penerapan hukum adat


Selain itu, pengakuan terhadap hukum adat juga dianggap sebagai bentuk penghormatan terhadap identitas budaya masyarakat Indonesia yang sangat beragam.



## Potensi Positif bagi Masyarakat

Jika diterapkan dengan tepat, aturan ini dinilai memiliki sejumlah dampak positif.

1. Melindungi Kearifan Lokal

Banyak komunitas adat memiliki nilai-nilai sosial yang selama ini membantu menjaga ketertiban masyarakat. Pengakuan negara terhadap hukum adat dapat membantu melestarikan budaya dan identitas lokal.

2. Penyelesaian Konflik Lebih Dekat dengan Masyarakat

Dalam beberapa kasus, penyelesaian berbasis adat dianggap lebih diterima masyarakat karena menggunakan pendekatan budaya lokal dan musyawarah.

Hal ini dinilai dapat membantu menyelesaikan konflik sosial secara lebih damai dan cepat.

3. Memperkuat Pengakuan terhadap Masyarakat Adat

Kebijakan ini juga dianggap sebagai bentuk pengakuan negara terhadap eksistensi masyarakat hukum adat yang selama ini sering merasa terpinggirkan dalam sistem hukum formal.



## Tantangan dan Kekhawatiran

Meski memiliki tujuan baik, aturan ini juga menghadapi sejumlah tantangan besar.

1. Risiko Multitafsir

Karena Indonesia memiliki ribuan adat dan budaya yang berbeda, penerapan hukum adat berpotensi menimbulkan multitafsir antar daerah.

Apa yang dianggap pelanggaran adat di satu wilayah belum tentu berlaku di daerah lain.

2. Potensi Pelanggaran HAM

Sejumlah pihak khawatir jika hukum adat diterapkan tanpa pengawasan ketat, maka dapat muncul praktik diskriminatif atau penghukuman yang bertentangan dengan hak asasi manusia.

Karena itu, pemerintah menegaskan bahwa seluruh penerapan hukum adat tetap harus tunduk pada konstitusi dan prinsip HAM.



3. Kesiapan Aparat Penegak Hukum

Penerapan aturan ini juga membutuhkan kesiapan aparat penegak hukum dan pemerintah daerah agar tidak terjadi kesalahan dalam penafsiran maupun pelaksanaan.

Tanpa pemahaman yang baik, aturan ini berisiko memunculkan konflik baru di masyarakat.



## Bagaimana Masa Depannya?

Ke depan, implementasi hukum adat dalam sistem hukum nasional diperkirakan masih akan terus berkembang.

Pemerintah kemungkinan akan melakukan evaluasi secara bertahap terhadap penerapan aturan ini di berbagai daerah. Pengawasan yang ketat serta sosialisasi kepada masyarakat menjadi faktor penting agar tujuan pengakuan hukum adat tidak berubah menjadi masalah baru.

Banyak pihak berharap kebijakan ini dapat menjadi jalan tengah antara menjaga budaya lokal dan tetap menjunjung prinsip hukum modern serta hak asasi manusia.




## Kesimpulan

Penerbitan aturan pelaksana hukum adat menjadi langkah penting dalam perjalanan sistem hukum Indonesia.

Negara kini mulai memberi ruang lebih besar terhadap hukum yang hidup di masyarakat, namun tetap dengan batasan yang jelas agar tidak bertentangan dengan konstitusi dan hak asasi manusia.

Jika diterapkan secara hati-hati dan terukur, kebijakan ini berpotensi memperkuat pengakuan budaya lokal sekaligus menjaga ketertiban sosial. Namun tanpa pengawasan yang baik, penerapannya juga bisa menimbulkan polemik baru di tengah masyarakat.

